import sympy
from sympy import gcd, sympify, simplify, eye, zeros

# Top-level setup for potential witness expressions
I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

CONDITION_LABELS = [
    "H_1: I is a principal ideal of R generated by an element a",
    "H_2: J is a principal ideal of R generated by an element b",
    "¬Q: The product ideal IJ is NOT generated by the product element ab"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    # Extract a and b from the witness
    try:
        if isinstance(witness, (tuple, list)):
            if len(witness) == 2:
                a, b = witness
            elif len(witness) == 3:
                a, b = witness[1], witness[2]
            elif len(witness) == 4:
                a, b = witness[1], witness[3]
            elif len(witness) == 5:
                a, b = witness[2], witness[4]
            else:
                a, b = witness[-2], witness[-1]
        else:
            return [False, False, False]
    except Exception:
        return [False, False, False]

    # Check H_1 and H_2: a and b are valid elements of the same ring
    try:
        is_mat_a = getattr(a, 'is_Matrix', False)
        is_mat_b = getattr(b, 'is_Matrix', False)
        
        if is_mat_a and is_mat_b:
            h1 = (a.rows == a.cols) and (a.rows > 0)
            h2 = (b.rows == b.cols) and (a.shape == b.shape)
        elif not is_mat_a and not is_mat_b:
            # Check if they support basic ring operations
            _ = a + a
            _ = a * a
            _ = b + b
            _ = b * b
            _ = a * b
            h1 = True
            h2 = True
        else:
            h1 = False
            h2 = False
    except Exception:
        h1 = False
        h2 = False

    # Check ¬Q: The product ideal IJ is NOT generated by ab
    try:
        def get_ideal_gen(x):
            # For matrices over a PID (like Z or Q[x]), the two-sided ideal 
            # is generated by the gcd of all its entries.
            if getattr(x, 'is_Matrix', False):
                if len(x) == 0:
                    return sympify(0)
                g = x[0]
                for val in x[1:]:
                    g = gcd(g, val)
                return g
            else:
                return sympify(x)
                
        k_a = get_ideal_gen(a)
        k_b = get_ideal_gen(b)
        k_ab = get_ideal_gen(a * b)
        
        # The product of the ideals is generated by the product of their generators
        prod = k_a * k_b
        
        # If the ideal generated by ab is strictly smaller/different, 
        # their canonical generators will differ.
        diff = simplify(prod - k_ab)
        neg_q = (diff != 0)
        
    except Exception:
        neg_q = False

    return [bool(h1), bool(h2), bool(neg_q)]